// Verify Greenhouse webhook HMAC-SHA256 signature.
// Greenhouse sends the signature in the header 'Signature' as:
//   sha256 <hex-digest>      (algorithm, a SPACE, then the hex digest)
// NOT 'sha256=<hex-digest>'. We split on the space and compare against the hash.
// The HMAC must be computed over the EXACT raw request body bytes Greenhouse sent
// (Unicode escaped as \uXXXX), so the Webhook node is configured with rawBody: true.
// The secret is set on the webhook in the Greenhouse Dev Center.

const crypto = require('crypto');

const secret = $env['GREENHOUSE_WEBHOOK_SECRET'] || '';
const headers = $input.first().json.headers || {};
const signatureHeader = (headers['signature'] || headers['Signature'] || '').trim();

// With rawBody: true the Webhook node exposes the original bytes as a base64
// binary property named 'data'. Decode those bytes for the HMAC so the digest
// byte-matches Greenhouse's original payload. Fall back to the rawBody string if
// present; only as a last resort re-stringify (which will not match Greenhouse's
// Unicode escaping and is provided to avoid a hard crash, not for verification).
let rawBodyBuf = null;
const binary = $input.first().binary;
if (binary?.data?.data) {
  rawBodyBuf = Buffer.from(binary.data.data, 'base64');
} else if (typeof $input.first().json.rawBody === 'string') {
  rawBodyBuf = Buffer.from($input.first().json.rawBody, 'utf8');
} else if (Buffer.isBuffer($input.first().json.rawBody)) {
  rawBodyBuf = $input.first().json.rawBody;
} else {
  rawBodyBuf = Buffer.from(JSON.stringify($input.first().json.body || {}), 'utf8');
}

if (!secret) {
  throw new Error('GREENHOUSE_WEBHOOK_SECRET env var is not set. Cannot verify signature.');
}

if (!signatureHeader) {
  throw new Error('No Signature header found in webhook request. Rejecting.');
}

// Header is 'sha256 <hex>'. Take everything after the first space as the digest.
const spaceIdx = signatureHeader.indexOf(' ');
const receivedHex = (spaceIdx === -1 ? signatureHeader : signatureHeader.slice(spaceIdx + 1)).trim().toLowerCase();

const expectedHex = crypto
  .createHmac('sha256', secret)
  .update(rawBodyBuf)
  .digest('hex');

// Constant-time compare. Both buffers must be the same length for timingSafeEqual,
// so guard on length first (a length mismatch is itself a failed verification).
const receivedBuf = Buffer.from(receivedHex, 'hex');
const expectedBuf = Buffer.from(expectedHex, 'hex');
if (receivedBuf.length !== expectedBuf.length || !crypto.timingSafeEqual(receivedBuf, expectedBuf)) {
  throw new Error('Signature mismatch. Dropping webhook (computed HMAC did not match the Signature header).');
}

// Verified. Extract the fields we need for the rest of the flow.
const payload = $input.first().json.body?.payload || $input.first().json.body || {};
const application = payload.application || {};
const candidate = application.candidate || payload.candidate || {};
const job = application.jobs?.[0] || payload.job || {};
const currentStage = payload.current_stage || application.current_stage || {};

// Collect interviewers from the current stage's interviews array.
// Each interview has an interviewers[] array with email addresses.
const interviews = currentStage.interviews || [];
const interviewerEmails = [];
for (const interview of interviews) {
  for (const iv of (interview.interviewers || [])) {
    if (iv.email && !interviewerEmails.includes(iv.email)) {
      interviewerEmails.push(iv.email);
    }
  }
}

// Recruiter email comes from the organizer field of the application or the
// assigned recruiter on the job.
const recruiterEmail = application.recruiter?.email ||
                       payload.recruiter?.email ||
                       job.recruiter?.email || '';

return [{
  json: {
    applicationId: String(application.id || ''),
    candidateName: candidate.name || `${candidate.first_name || ''} ${candidate.last_name || ''}`.trim(),
    candidateEmail: (candidate.email_addresses || []).find(e => e.type === 'work')?.value ||
                    (candidate.email_addresses || [])[0]?.value || candidate.email || '',
    jobId: String(job.id || ''),
    jobName: job.name || '',
    stageName: currentStage.name || '',
    recruiterEmail,
    interviewerEmails,
    allCalendarIds: [...new Set([recruiterEmail, ...interviewerEmails].filter(Boolean))],
    greenhouseApplicationId: String(application.id || ''),
    receivedAt: new Date().toISOString(),
  }
}];

// Candidate availability intake stub.
// In a real deployment this node reads from a Typeform / Calendly webhook response
// or from a candidate-facing availability form whose results were stored in Airtable/Google Sheets.
// For the initial run, the node returns a wide open window (the full 14-day range)
// so the conflict-resolution logic can compute panel availability unconditionally.
// Replace this node with a Typeform, Airtable, or Google Sheets read node once
// you have a candidate-availability collection step wired.

const applicationId = $('Verify Signature + Extract Participants').first().json.applicationId;
const candidateName = $('Verify Signature + Extract Participants').first().json.candidateName;

// Build a set of wide-open candidate windows:
// Mon-Fri 9am-6pm ET for each day in the next 14 days.
const windows = [];
const tz = 'America/New_York';
const now = new Date();
for (let d = 1; d <= 14; d++) {
  const date = new Date(now);
  date.setDate(date.getDate() + d);
  const dow = date.getDay(); // 0=Sun, 6=Sat
  if (dow === 0 || dow === 6) continue;
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  windows.push({
    start: `${yyyy}-${mm}-${dd}T09:00:00-05:00`,
    end:   `${yyyy}-${mm}-${dd}T18:00:00-05:00`,
  });
}

return [{
  json: {
    applicationId,
    candidateName,
    candidateWindows: windows,
    source: 'stub-wide-open',
  }
}];

// Conflict-resolution algorithm: free-window intersection + slot ranking.
//
// INPUTS:
//   $('Google Calendar — freeBusy Query').first().json  → freeBusy API response
//   $('Candidate Availability Intake').first().json      → candidateWindows[]
//   $('Verify Signature + Extract Participants').first().json → allCalendarIds, recruiterEmail
//
// ALGORITHM:
//   1. For each panel member, collect their busy intervals from the freeBusy response.
//   2. Build the candidate's free intervals from candidateWindows.
//   3. Intersect all participant free windows to find slots when *everyone* is free.
//   4. Quantize to 60-minute blocks (configurable via SLOT_DURATION_MINUTES below).
//   5. Apply tie-break preference rules to rank the candidate slots:
//        a. Earlier in the day beats later (candidates respond better to morning slots).
//        b. Days with fewer total busy intervals for the recruiter are preferred
//           (lighter-schedule days leave room for immediate debrief).
//        c. Never propose slots straddling noon (11:30–12:30 ET) — lunch collision.
//   6. Return the top 3 ranked slots.

const SLOT_DURATION_MINUTES = 60;
const MAX_PROPOSALS = 3;
const NOON_BUFFER_MINUTES = 30; // exclude slots starting within 30 min of noon
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000; // America/New_York standard; DST not applied here — use a DST-aware library in production

// Parse ISO string to ms timestamp.
function toMs(iso) { return new Date(iso).getTime(); }
function toISO(ms) { return new Date(ms).toISOString(); }

// Merge overlapping/adjacent intervals (sorted by start).
function mergeIntervals(intervals) {
  if (!intervals.length) return [];
  const sorted = [...intervals].sort((a, b) => a.start - b.start);
  const merged = [sorted[0]];
  for (let i = 1; i < sorted.length; i++) {
    const last = merged[merged.length - 1];
    if (sorted[i].start <= last.end) {
      last.end = Math.max(last.end, sorted[i].end);
    } else {
      merged.push({ ...sorted[i] });
    }
  }
  return merged;
}

// Subtract busy intervals from a free window, returning the remaining free sub-intervals.
function subtractBusy(freeWindow, busyIntervals) {
  let remaining = [{ ...freeWindow }];
  for (const busy of busyIntervals) {
    const next = [];
    for (const free of remaining) {
      if (busy.end <= free.start || busy.start >= free.end) {
        next.push(free); // no overlap
      } else {
        if (busy.start > free.start) next.push({ start: free.start, end: busy.start });
        if (busy.end < free.end)   next.push({ start: busy.end,   end: free.end });
      }
    }
    remaining = next;
  }
  return remaining;
}

// --- Build per-participant busy intervals ---
const freeBusyResponse = $('Google Calendar — freeBusy Query').first().json;
const { allCalendarIds, recruiterEmail } = $('Verify Signature + Extract Participants').first().json;

const participantBusy = {};
for (const calId of allCalendarIds) {
  const calData = freeBusyResponse.calendars?.[calId];
  if (!calData) {
    participantBusy[calId] = []; // calendar not found or no access — treat as free
    continue;
  }
  if (calData.errors?.length) {
    // Calendar returned an error (e.g. notFound, restricted).
    // Log it and treat as free so we don't block on one unavailable calendar.
    console.warn(`freeBusy error for ${calId}:`, JSON.stringify(calData.errors));
    participantBusy[calId] = [];
    continue;
  }
  participantBusy[calId] = (calData.busy || []).map(b => ({
    start: toMs(b.start),
    end:   toMs(b.end),
  }));
}

// Merge all participant busy intervals into a single union (the panel is blocked
// if ANY member is busy).
const allBusy = Object.values(participantBusy).flat();
const mergedPanelBusy = mergeIntervals(allBusy);

// Count how many busy intervals the recruiter has per calendar-day (tie-break input).
const recruiterBusyByDay = {};
for (const interval of (participantBusy[recruiterEmail] || [])) {
  const dayKey = new Date(interval.start).toISOString().slice(0, 10);
  recruiterBusyByDay[dayKey] = (recruiterBusyByDay[dayKey] || 0) + 1;
}

// --- Candidate free windows ---
const { candidateWindows } = $('Candidate Availability Intake').first().json;
const candidateFreeIntervals = candidateWindows.map(w => ({
  start: toMs(w.start),
  end:   toMs(w.end),
}));

// --- Compute free intersection ---
// For each candidate window, subtract the merged panel busy intervals.
const freeSlots = []; // { start: ms, end: ms }
for (const window of candidateFreeIntervals) {
  const overlappingBusy = mergedPanelBusy.filter(b => b.end > window.start && b.start < window.end);
  const freeInWindow = subtractBusy(window, overlappingBusy);
  freeSlots.push(...freeInWindow);
}

// --- Quantize to SLOT_DURATION_MINUTES blocks ---
const slotMs = SLOT_DURATION_MINUTES * 60 * 1000;
const candidates = [];
for (const free of freeSlots) {
  let t = free.start;
  // Round up to next 30-min boundary to align to :00 or :30.
  const thirtyMin = 30 * 60 * 1000;
  if (t % thirtyMin !== 0) {
    t = Math.ceil(t / thirtyMin) * thirtyMin;
  }
  while (t + slotMs <= free.end) {
    const slotStart = new Date(t);
    const hour = slotStart.getUTCHours() + (TZ_OFFSET_MS / (60 * 60 * 1000));
    const minute = slotStart.getUTCMinutes();
    // Exclude slots straddling noon (11:30-12:00 start = ends at 12:30-13:00).
    const hourFraction = hour + minute / 60;
    if (!(hourFraction >= 11.5 - SLOT_DURATION_MINUTES / 60 && hourFraction < 12)) {
      candidates.push({ start: t, end: t + slotMs });
    }
    t += slotMs;
  }
}

// --- Rank slots ---
// Score = base 100
//   - Subtract (localHour - 9) * 5  → earlier is better (9am = 0 penalty, 5pm = 40 penalty)
//   - Subtract recruiterBusyByDay[day] * 3 → lighter recruiter day preferred
//   - Add 10 if slot is in the first 5 business days (urgency preference)
const ranked = candidates.map(slot => {
  const d = new Date(slot.start);
  const dayKey = d.toISOString().slice(0, 10);
  const localHour = d.getUTCHours() + (TZ_OFFSET_MS / (60 * 60 * 1000));
  const recruiterLoad = recruiterBusyByDay[dayKey] || 0;
  const score = 100
    - (localHour - 9) * 5
    - recruiterLoad * 3
    + (candidates.indexOf(slot) < 10 ? 10 : 0); // first 10 candidate slots are in the near-term
  return { ...slot, score, dayKey, localHour };
}).sort((a, b) => b.score - a.score);

const top = ranked.slice(0, MAX_PROPOSALS);

if (top.length === 0) {
  return [{
    json: {
      resolved: false,
      reason: 'no_common_availability',
      applicationId: $('Verify Signature + Extract Participants').first().json.applicationId,
      recruiterEmail,
      message: 'No overlapping free windows found in the 14-day lookahead. Routing to manual coordinator.',
    }
  }];
}

return [{
  json: {
    resolved: true,
    applicationId: $('Verify Signature + Extract Participants').first().json.applicationId,
    candidateName: $('Candidate Availability Intake').first().json.candidateName,
    recruiterEmail,
    allCalendarIds,
    proposedSlots: top.map(s => ({
      start: toISO(s.start),
      end:   toISO(s.end),
      score: s.score,
    })),
    slotsEvaluated: candidates.length,
    panelBusyIntervalCount: mergedPanelBusy.length,
  }
}];

