// Client-side filter for stale UNSCHEDULED interviews.
// The Harvest scheduled_interviews endpoint has no 'status' query param, so the
// HTTP node fetched ALL interviews created >48h ago. Here we keep only the ones
// that still have no confirmed time slot — i.e. the ones the resolver should chase.
//
// A scheduled_interviews record carries:
//   status: 'scheduled' | 'awaiting_feedback' | 'complete'
//   start:  { date_time: <ISO> } | { date: <YYYY-MM-DD> } | null when unscheduled
//   interviewers[]: { response_status: 'needs_action'|'declined'|'tentative'|'accepted', ... }
//
// 'Unscheduled / stale' = no concrete start.date_time has been set yet. We also
// exclude anything already complete or awaiting feedback (those are past the
// scheduling stage). Records the API returns as a bare array land in $json.body
// (HTTP node: fullResponse:false). With neverError:true, an error response would
// not be an array — guard for that and emit nothing rather than crash.

const raw = $input.first().json.body;
const interviews = Array.isArray(raw) ? raw : (Array.isArray(raw?.body) ? raw.body : []);

const stale = interviews.filter((iv) => {
  if (!iv || typeof iv !== 'object') return false;
  // Already scheduled with a concrete time → not our problem.
  const hasConfirmedTime = !!(iv.start && iv.start.date_time);
  if (hasConfirmedTime) return false;
  // Past the scheduling stage entirely.
  if (iv.status === 'complete' || iv.status === 'awaiting_feedback') return false;
  return true;
});

// Re-wrap as a single item carrying the filtered array under 'body' so the
// downstream Split Out node (fieldToSplitOut: 'body') can fan it back out.
return [{ json: { body: stale, fetchedCount: interviews.length, staleCount: stale.length } }];
